# PERFORMANCE MONITORING AND ANALYTICS
class QuantumPerformanceMonitor:
    """Real-time performance monitoring for quantum operations"""

    def __init__(self):
        self.metrics = {
            "total_requests": 0,
            "successful_operations": 0,
            "failed_operations": 0,
            "average_execution_time": 0.0,
            "quantum_advantage_rate": 0.0,
            "revenue_per_hour": 0.0,
            "algorithm_usage": {},
            "performance_history": []
        }

    def log_operation(self, result: QuantumResult, revenue: float):
        """Log quantum operation metrics"""
        self.metrics["total_requests"] += 1

        if result.quality_score > 0:
            self.metrics["successful_operations"] += 1
        else:
            self.metrics["failed_operations"] += 1

        # Update averages
        current_avg = self.metrics["average_execution_time"]
        n = self.metrics["total_requests"]
        self.metrics["average_execution_time"] = ((current_avg * (n-1)) + result.execution_time) / n

        # Track algorithm usage
        algo = result.algorithm
        if algo not in self.metrics["algorithm_usage"]:
            self.metrics["algorithm_usage"][algo] = 0
        self.metrics["algorithm_usage"][algo] += 1

        # Quantum advantage rate
        if result.classical_comparison and result.quality_score > 0:
            success_rate = self.metrics["successful_operations"] / self.metrics["total_requests"]
            self.metrics["quantum_advantage_rate"] = success_rate * 100

        # Performance history
        self.metrics["performance_history"].append({
            "timestamp": datetime.now().isoformat(),
            "algorithm": algo,
            "execution_time": result.execution_time,
            "quality_score": result.quality_score,
            "revenue": revenue
        })

        # Keep only last 100 entries
        if len(self.metrics["performance_history"]) > 100:
            self.metrics["performance_history"] = self.metrics["performance_history"][-100:]

    def generate_performance_report(self) -> Dict[str, Any]:
        """Generate comprehensive performance report"""
        if self.metrics["total_requests"] == 0:
            return {"error": "No operations recorded yet"}

        # Calculate revenue rate (last hour simulation)
        recent_operations = self.metrics["performance_history"][-10:]  # Last 10 operations
        recent_revenue = sum(op.get("revenue", 0) for op in recent_operations)
        self.metrics["revenue_per_hour"] = recent_revenue * 6  # Extrapolate to hourly

        return {
            "performance_summary": {
                "total_operations": self.metrics["total_requests"],
                "success_rate": (self.metrics["successful_operations"] / self.metrics["total_requests"]) * 100,
                "average_execution_time": f"{self.metrics['average_execution_time']:.3f}s",
                "quantum_advantage_rate": f"{self.metrics['quantum_advantage_rate']:.1f}%",
                "estimated_hourly_revenue": f"${self.metrics['revenue_per_hour']:.2f}"
            },
            "algorithm_popularity": self.metrics["algorithm_usage"],
            "recent_operations": recent_operations,
            "system_health": "Excellent" if self.metrics["quantum_advantage_rate"] > 50 else "Good" if self.metrics["quantum_advantage_rate"] > 20 else "Needs Attention"
        }

